//! Detached Attr factories retain genuine owner and document-specific case.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn attribute_filter_units_exact_names_case_namespace_duplicates_and_snapshot_are_real(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var node=document.getElementById('mount'),raw='data-\ud800',other='data-\udfff',replacement='data-\ufffd',names=[raw,raw],selected=new MutationObserver(function(){}),all=new MutationObserver(function(){}),upper=new MutationObserver(function(){});selected.observe(node,{attributeFilter:names,attributeOldValue:true});all.observe(node,{attributes:true,attributeOldValue:true});upper.observe(node,{attributeFilter:['DATA-\ud800']});names[0]=replacement;names[1]=replacement;node.setAttribute(raw,'one');node.setAttribute(replacement,'literal');node.setAttribute(other,'other');node.setAttributeNS('urn:attribute','p:'+raw,'namespaced');node.setAttribute(raw,'two');var records=selected.takeRecords(),every=all.takeRecords();if(records.length!==2||every.length!==5||upper.takeRecords().length||records[0].attributeName!==raw||records[0].attributeNamespace!==null||records[0].oldValue!==null||records[1].oldValue!=='one'||records[1].attributeName!==raw||every[3].attributeNamespace!=='urn:attribute'||every[3].attributeName!==raw)throw 'exact snapshot filter without case fold or namespace alias';selected.observe(node,{attributeFilter:[]});node.setAttribute(raw,'empty-filter');if(selected.takeRecords().length)throw 'empty sequence has no name matches';selected.observe(node,{attributeFilter:[replacement],attributeOldValue:true});node.setAttribute(raw,'unselected');node.setAttribute(replacement,'next');records=selected.takeRecords();if(records.length!==1||records[0].attributeName!==replacement||records[0].oldValue!=='literal')throw 'real updated exact filter';var xml=document.implementation.createDocument(null,'Root'),mixed='MiXeD\ud800';selected.observe(xml.documentElement,{attributeFilter:[mixed],attributeOldValue:true});xml.documentElement.setAttribute(mixed,'inert');xml.documentElement.setAttribute('mixed\ud800','unselected');records=selected.takeRecords();if(records.length!==1||records[0].target!==xml.documentElement||records[0].attributeName!==mixed||records[0].oldValue!==null)throw 'inert XML case-sensitive exact filter';
"#);
}
#[test]
fn attribute_filter_units_dictionary_iterator_order_reentry_close_and_refusal_keep_subscription(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var node=document.getElementById('mount'),raw='data-\ud800',watch=new MutationObserver(function(){}),order='',names=[raw];watch.observe(node,{attributeFilter:['data-old'],attributeOldValue:true});var iterable={[Symbol.iterator]:function(){order+='i';var used=false;return {next:function(){if(used){order+='d';return {done:true};}used=true;order+='n';return {done:false,value:{toString:function(){order+='s';node.setAttribute('data-old','callback');return raw;}}};}};}};watch.observe(node,{get attributeFilter(){order+='f';return iterable;},get attributeOldValue(){order+='o';names[0]='data-\ufffd';return true;},get attributes(){order+='a';return true;}});if(order!=='finsdoa')throw 'ordered dictionary and iterator conversions';var records=watch.takeRecords();if(records.length!==1||records[0].attributeName!=='data-old')throw 'conversion callback used actual old registration';var closed=0,caught=false,bad={[Symbol.iterator]:function(){return {next:function(){return {done:false,value:Symbol('invalid')};},return:function(){closed++;return {};}};}};try{watch.observe(node,{attributeFilter:bad});}catch(e){caught=e instanceof TypeError;}if(!caught||closed!==1)throw 'DOMString failure closes iterator';node.setAttribute(raw,'retained');node.setAttribute('data-\ufffd','ignored');records=watch.takeRecords();if(records.length!==1||records[0].attributeName!==raw)throw 'failed conversion did not replace old filter';
"#);
}
#[test]
fn attribute_filter_units_saved_child_origin_precedes_options_or_iterator_work(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var node=document.getElementById('mount'),watch=new MutationObserver(function(){}),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var observe=frame.contentWindow.Function('observer','node','options','observer.observe(node,options);'),calls=0,options={get attributeFilter(){calls++;return ['data-\ud800'];}};observe(watch,node,options);if(calls!==1)throw 'actual child observe';
"#);page.set_location(&crate::navigation::address("https://other-filter-units.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"observe(watch,node,options);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(calls!==1)throw 'origin before filter dictionary';node.setAttribute('data-\\ud800','retained');if(watch.takeRecords().length!==1)throw 'old genuine registration retained';");
}
